package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateEmailException;

/**
 * Rejects a create-owner request whose lower-cased email already belongs to another owner.
 * Runs after {@link NormalizeOwnerEmail} (so {@code request.getEmail()} is already stored
 * lower-cased, or null when the optional email was omitted) and before {@link SaveOwner}.
 * Every stored owner's email is lower-cased the same way before comparison, so differently
 * cased spellings of the same address still collide. On a match raises
 * {@link DuplicateEmailException} (409). A request without an email is left untouched.
 */
public class CheckOwnerEmailUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateEmailException {
        String email = request.getEmail();
        if (email == null || email.isBlank()) {
            return;
        }
        for (Owner existing : ownerRepository.findAll()) {
            String existingEmail = existing.getEmail();
            if (existingEmail != null && email.equals(existingEmail.toLowerCase(Locale.ROOT))) {
                throw new DuplicateEmailException(email);
            }
        }
    }
}
===== CheckOwnerHouseholdUnique =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;

/**
 * Rejects a create-owner request whose last name and address both match an existing owner's,
 * because they would form a duplicate household. Addresses are compared in their normalized
 * form (see {@link AddressNormalizer}: trimmed, whitespace-collapsed, upper-cased, with common
 * abbreviations expanded), so "12 Main St" and "12  main  street" collide; the last name is
 * compared case-insensitively with whitespace collapsed. A request may opt out of the rule
 * by setting {@code sharesHousehold=true}, which lets genuine housemates share an address.
 * On a match raises {@link DuplicateHouseholdException} (409).
 */
public class CheckOwnerHouseholdUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String lastName = normalize(request.getLastName());
        String address = AddressNormalizer.normalize(request.getAddress());
        for (Owner existing : ownerRepository.findAll()) {
            if (lastName.equals(normalize(existing.getLastName()))
                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))) {
                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
            }
        }
    }

    /** Lower-case, trim, and collapse internal whitespace runs to a single space. */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}
===== NormalizeOwnerTelephone =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;

/**
 * Normalizes the create-owner telephone into E.164 form and writes it back onto the body so
 * {@link BuildOwner} maps and {@link SaveOwner} stores the canonical value. A leading '+'
 * and country code are kept when present; otherwise country code '+61' is assumed and a
 * single leading '0' is dropped from the national digits. Spaces, dashes and brackets are
 * stripped. A number that cannot form a valid E.164 string (8 to 15 digits after the '+')
 * raises {@link InvalidTelephoneException} (400).
 *
 * <p>Runs after {@link ValidateOwnerFields} (which rejects a blank telephone) and mutates the
 * validated body in place — {@code @Val} yields the same object the earlier step published.
 */
public class NormalizeOwnerTelephone {

    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
        String e164 = TelephoneE164.toE164(request.getTelephone());
        if (!TelephoneE164.isValid(e164)) {
            throw new InvalidTelephoneException(e164 == null ? "" : e164);
        }
        request.setTelephone(e164);
    }
}
===== NormalizeOwnerEmail =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.regex.Pattern;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;

/**
 * Normalizes the owner {@code email}: it is optional, so a null or blank value is left
 * absent. When present it must be a syntactically valid address; otherwise
 * {@link InvalidEmailException} (400) is raised. A valid address is stored lower-cased on
 * the body so {@link BuildOwner}/{@link ApplyOwner} map and {@link SaveOwner} stores the
 * canonical form, and {@code GET} returns it lower-cased.
 *
 * <p>Mutates the validated body in place — {@code @Val} yields the same object the earlier
 * step published.
 */
public class NormalizeOwnerEmail {

    /** Requires a non-empty local part, an {@code @}, and a domain containing a dot,
     *  with no whitespace or extra {@code @}. Rejects values like {@code "not-an-email"}. */
    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");

    public void service(@Val OwnerFieldsDto request) throws InvalidEmailException {
        String email = request.getEmail();
        if (email == null || email.isBlank()) {
            request.setEmail(null);
            return;
        }
        if (!EMAIL.matcher(email).matches()) {
            throw new InvalidEmailException(email);
        }
        request.setEmail(email.toLowerCase(Locale.ROOT));
    }
}
===== AssignHousehold =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Assigns a shared {@code householdId} when a create-owner request opts in with
 * {@code sharesHousehold=true} and there is an existing owner with the same last name and
 * address (the address compared in its normalized form via {@link AddressNormalizer} — the
 * same rule {@link CheckOwnerHouseholdUnique} uses). The identifier is <em>stable</em>: it is derived
 * deterministically from the normalized last name and address, so every housemate computes
 * the same value regardless of creation order. The value is set on the newly built
 * {@link Owner} and back-filled onto the existing housemate(s) so both carry it.
 *
 * <p>Runs after {@link BuildOwner} (so the entity exists) and before {@link SaveOwner}; when
 * the request does not opt in, or opts in but has no existing household to join, it is a no-op.
 */
public class AssignHousehold {

    public void service(@Val OwnerFieldsDto request, @Val Owner built, OwnerRepository ownerRepository) {
        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String lastName = normalize(request.getLastName());
        String address = AddressNormalizer.normalize(request.getAddress());
        List<Owner> housemates = new ArrayList<>();
        for (Owner existing : ownerRepository.findAll()) {
            if (lastName.equals(normalize(existing.getLastName()))
                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))) {
                housemates.add(existing);
            }
        }
        if (housemates.isEmpty()) {
            return;
        }
        String householdId = householdId(lastName, address);
        built.setHouseholdId(householdId);
        for (Owner mate : housemates) {
            if (!householdId.equals(mate.getHouseholdId())) {
                mate.setHouseholdId(householdId);
                ownerRepository.save(mate);
            }
        }
    }

    /** A stable household identifier: first 12 upper-case hex chars of SHA-256 over the
     *  normalized last name and address, so all housemates derive the same value. */
    private static String householdId(String lastName, String address) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest((lastName + "|" + address).getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.substring(0, 12).toUpperCase();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 not available", e);
        }
    }

    /** Lower-case, trim, and collapse internal whitespace runs to a single space. */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}
===== BuildOwner =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

public class BuildOwner {

    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built) {
        Owner owner = ownerMapper.toOwner(request);
        // The effective registration date (supplied or defaulted to today) must fall on a
        // business day; a weekend rolls forward to the next Monday.
        owner.setRegistrationDate(BusinessDay.effective(request));
        built.set(owner);
    }
}
